# Confirm bot made it online and try to pull up idr names
@bot.event
async def on_ready():
    print("🔆  Radar Bot online  🔆")
    try:
        synced = await bot.tree.sync()
        print(f"Synced {len(synced)} slash command(s)")
    except Exception as e:
        print(f"Error syncing commands: {e}")
    
    try:

        print("📶  Reading IDR Sheet for Name list...")

        url_map = {
        'urlIDR': 'https://docs.google.com/spreadsheets/d/1LA98yHFoA4hXllPc4VZrflD-m526FJi0uq9IuboVNZw/export?format=csv&gid=130623301',

        'urlTEAM': 'https://docs.google.com/spreadsheets/d/1SnjRG89LGAEgMwsMlyU_gq9pJidGCcbLClqOlx6ubEk/export?format=csv&gid=0',

        }



        dfs = await asyncio.wait_for(fetch_sheets(url_map), timeout=15)

        df = dfs['urlIDR']

        dfTEAM = dfs['urlTEAM']

        bot.dfdat = df
        bot.dfteam = dfTEAM



        if "#n/a" in df["Tier"].str.casefold().tolist() or "#ref!" in df["Tier"].str.casefold().tolist():
            raise Exception("A sheet is down or missing info")

        print(f"✅  Lookup sheet parsed")

    except (Exception, asyncio.TimeoutError) as e:
    
        print(f"⚠️   Could not pull IDR sheet for Names: {e}. 🛄  Attempting to use cache now...")

        try:

            df = pd.read_csv('cache/dfI.csv')
            dfTEAM = pd.read_csv('cache/dfTEAM.csv')

            bot.dfdat = df
            bot.dfteam = dfTEAM

            print("✅  Lookup sheet pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframe for Name list: {e}.")


