#Try to update the cache:
async def update_cache(bot, url_map):
    while not bot.is_closed():

        bot.dfmast = pd.read_csv("cache/dfmast.csv")
        print("⬆️  Last cache uploaded  ⬆️")

        try:
            print("🔄  Attempting to update cache...  🔄")

            start_time = time.perf_counter()

            ######################################################################################################################################################################
            # region 1) sheet pulls and seasonal info
            ######################################################################################################################################################################

            url_map = {
            'urlIDR': 'https://docs.google.com/spreadsheets/d/1LA98yHFoA4hXllPc4VZrflD-m526FJi0uq9IuboVNZw/export?format=csv&gid=130623301',

            # 'urlSTAT': 'https://docs.google.com/spreadsheets/d/1456f26wF4QonD6OQC3Q5XElD2gUT0h97nCj-W5EORvU/export?format=csv&gid=678024960',

            'urlTOT': 'https://docs.google.com/spreadsheets/d/1456f26wF4QonD6OQC3Q5XElD2gUT0h97nCj-W5EORvU/export?format=csv&gid=1628277965',

            'urlAVG': 'https://docs.google.com/spreadsheets/d/1456f26wF4QonD6OQC3Q5XElD2gUT0h97nCj-W5EORvU/export?format=csv&gid=1181549404',

            'urlROSTER': 'https://docs.google.com/spreadsheets/d/1EPQVop9J6Hc15e0kGjNWfwE3_gxLisi1CBSLKOLD6H4/export?format=csv&gid=1016452913',

            'urlTEAM': 'https://docs.google.com/spreadsheets/d/1SnjRG89LGAEgMwsMlyU_gq9pJidGCcbLClqOlx6ubEk/export?format=csv&gid=0',

            }

            season = 26

            #Try to pull the sheets from online

            bot.dfetch = await asyncio.wait_for(fetch_sheets(url_map), timeout=60)

            dfI = bot.dfetch['urlIDR']

            dfAVG = bot.dfetch['urlAVG']

            dfTOT = bot.dfetch['urlTOT']
            dfTEAM = bot.dfetch['urlTEAM']
            dfROSTER = bot.dfetch['urlROSTER']
            careerlist = pd.read_csv('careercache/careerlist.csv')

            if "#n/a" in dfI["Tier"].str.casefold().tolist() or "#ref!" in dfI["Tier"].str.casefold().tolist() or "veteran" not in dfTOT["Tier"].astype(str).str.lower().values:
                raise Exception("A sheet is down or missing info")

            if 1 == 1:
                if "premier" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "master" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "elite" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "veteran" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "rival" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "challenger" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "prospect" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "contender" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "amateur" not in dfTOT["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")

                elif "premier" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "master" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "elite" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "veteran" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "rival" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "challenger" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "prospect" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "contender" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")
                elif "amateur" not in dfI["Tier"].astype(str).str.lower().values:
                    raise Exception("A sheet is down or missing info")

            end_time = time.perf_counter()

            duration = end_time - start_time

            print(f"✅  Sheets parsed in {duration: .2f} seconds. Loading master dataframe...")

            ######################################################################################################################################################################
            # region 2) season and rosters
            ######################################################################################################################################################################

            # value_to_remove = str("Rival")

            dfI = dfI[~dfI["Tier"].str.contains('Rival', case=False, na=False)]

            #Create Master DF

            df = dfI[["RSC ID", "Tier", "Name", "GP",]]

            #Current Season

            df["Season"] = int(season)

            #Import players' # of seasons played and find their first season

            keys = ["RSC ID"]

            df = pd.merge(
                df, careerlist[keys + ["# of Seasons", "First Season", "Seasons Played"]],
                on=keys,
                how="left"
            )

            df["# of Seasons"] = df["# of Seasons"].fillna(0)
            df["First Season"] = df["First Season"].fillna(season)

            #merge tiers to contracts

            keys = ["Team"]

            dfROSTER = pd.merge(
                dfROSTER, dfTEAM[keys + ["Tier"]],
                on=keys,
                how="left"
            )

            #Get players' teams and franchises from roster sheet

            keys = ["RSC ID", "Tier"]

            df = pd.merge(
                df, dfROSTER[keys + ["Team", "Franchise"]],
                on=keys,
                how="left"
            )

            #Get players' current contracts

            keys = ["RSC ID"]

            df = pd.merge(
                df, dfROSTER[keys + ["Contract Status"]],
                on=keys,
                how="left"
            )

            #At this point only rostered players in their own tier should have teams...

            ros = df[df['Team'].isna()]

            signed = ["Rostered", "Inactive Reserve"]

            mask = ros["Contract Status"].isin(signed)

            count = mask.sum()


            if count > 0:

                # find cross-tier subs

                ro = ros[ros["Contract Status"].isin(signed)]

                #Get players' teams played for in the tier

                keys = ["RSC ID", "Tier"]

                ro = pd.merge(
                    ro, dfTOT[keys + ["Team(s)",]],
                    on=keys,
                    how="left"
                )

                #Get most recent team

                ro["Team(s)"] = (
                    ro["Team(s)"]
                    .astype("string")                 # keeps <NA> nicely
                    .str.split(r"\r?\n")   # split on newline
                    .apply(lambda x: x[-1].strip() if x is not pd.NA else pd.NA)
                )            

                dropthis = ['Team', "Franchise"]

                ro.drop(columns=dropthis, inplace=True)

                ro = ro.rename(columns={"Team(s)": "Team"})



                keys = ["Team"]

                ro = pd.merge(
                    ro, dfTEAM[keys + ["Franchise"]],
                    on=keys,
                    how="left"
                )

                ro["Contract Status"] = ro["Contract Status"].replace('Rostered', 'Cross-Tier Sub')

                key_cols = ["RSC ID", "Tier"]  # example keys that uniquely identify a row

                df = df.set_index(key_cols)
                ro = ro.set_index(key_cols)

                df["Team"] = df["Team"].combine_first(ro["Team"])   # fill only where df team is NaN



                df["Franchise"] = df["Franchise"].combine_first(ro["Franchise"])

                df = df.reset_index()
                ro = ro.reset_index()

                keys = ["RSC ID", "Tier"]          # <- your identifiers
                cols = ["Contract Status"]  

                df_i = df.set_index(keys)
                ro_i = ro.set_index(keys)  

                df_i.update(ro_i[cols])
                df = df_i.reset_index()

            #At this point only free agent should be left...  

            mask1 = df["Team"].isna() & (df["Contract Status"] == "Permanent Free Agent")

            df.loc[mask1, "Team"] = "PermFA"
            df.loc[mask1, "Franchise"] = "PermFA"

            mask1 = df["Team"].isna() & (df["Contract Status"] == "Free Agent")

            df.loc[mask1, "Team"] = "Free Agent"
            df.loc[mask1, "Franchise"] = "Free Agent"

            mask1 = df["Team"].isna() & (df["Contract Status"] == "Waivers")

            df.loc[mask1, "Team"] = "Free Agent"
            df.loc[mask1, "Franchise"] = "Free Agent"

            mask1 = df["Team"].isna() & (df["Contract Status"].str.contains("Dropped|Former"))

            df.loc[mask1, "Team"] = "Former"
            df.loc[mask1, "Franchise"] = "Former"

            #Find conference

            keys = ["Team"]

            df = pd.merge(
                df, dfTEAM[keys + ["Conf"]],
                on=keys,
                how="left"
            )

            df = df.rename(columns={"Conf": "Conference"})

            df["Conference"] = df["Conference"].fillna("N/A")


            ######################################################################################################################################################################
            # region 3) stat pulls from sheets and normalization
            ######################################################################################################################################################################

            #Get players' stats from IDR sheet

            keys = ["RSC ID", "Tier"]

            df = pd.merge(
                df, dfI[keys + ["Shot %", "PPG", "GPG", "APG", "SvPG", "ShPG", 'PAPG', 'GAPG', 'AAPG', 'SvAPG', 'ShAPG']],
                on=keys,
                how="left"
            )

            

            df = df.rename(columns={"Shot %": "ShPCT",})

            #turn Shot % values into floats

            df["ShPCT"] = df["ShPCT"].fillna(.01)

            df['ShPCT'] = df['ShPCT'].str.rstrip('%').astype(float)

            #Import players' accolades from RPV sheet
            keys = ["RSC ID", "Tier"]

            df = pd.merge(
                df, dfTOT[keys + ["Hat Trick", "Playmaker", "Savior"]],
                on=keys,
                how="left"
            )

            #Import players' demo and position statistics from stats sheet

            keys = ["RSC ID", "Tier"]
            df = pd.merge(
                df, dfAVG[keys + ["demos inflicted", "demos taken", "percentage defensive third", "percentage defensive half", 'percentage neutral third', "percentage offensive half", 'percentage offensive third']],
                on=keys,
                how="left"
            )

            df = df.rename(columns={"demos inflicted": 'DI', "demos taken": 'DT',  "percentage defensive third": 'pdt', "percentage defensive half": 'pdh', 'percentage neutral third': 'pnt', "percentage offensive half": 'poh', 'percentage offensive third': 'pot'})

            ######################################################################################################################################################################
            # region 4) new stat creation
            ######################################################################################################################################################################

            numeric_cols = ["GP", "PPG", "GPG", "APG", "ShPG", "ShPCT", "SvPG", "GAPG", "AAPG", "ShAPG", "Hat Trick", "Playmaker", "Savior"]

            for col in numeric_cols:
                df[col] = pd.to_numeric(df[col], errors="coerce")


            #Handle 0s for division purposes

            df["GAPG"] = df["GAPG"].replace(0, .01)
            df["AAPG"] = df["AAPG"].replace(0, .01)
            df["ShAPG"] = df["ShAPG"].replace(0, .01)

            df["GAPG"] = df["GAPG"].fillna(.01)
            df["AAPG"] = df["AAPG"].fillna(.01)
            df["ShAPG"] = df["ShAPG"].fillna(.01)
            df["ShPCT"] = df["ShPCT"].fillna(.01)

            #Create the RAW stat:
            
            df["MAJ"] = ((df["GPG"] * 100) + (df["APG"] * 50) + (df["SvPG"] * 57) + (df["ShPG"] * 10)).round(2)
            df["EXT"] = (df["PPG"] - df["MAJ"]).round(2)

            df["ACC"] = (df["Hat Trick"] + df["Playmaker"] + df["Savior"]).round(2)

            df["ACC"] = df["ACC"].fillna(.01)

            df["NEG"] = ((df["ACC"] / df["GP"]) * 25).round(2)

            df["RAW"] = (df["EXT"] - df["NEG"]).round(2)

            ### Zones, AFP, and Tz ###

            df["pdt"] = ((df["pdt"] / 100)).round(3)

            df["pdh"] = ((df["pdh"] / 100)).round(3)

            df["pnt"] = ((df["pnt"] / 100)).round(3)

            df["poh"] = ((df["poh"] / 100)).round(3)

            df["pot"] = ((df["pot"] / 100)).round(3)

            df["z1"] = df["pdt"]

            df["z2"] = (df["pdh"] - df["pdt"]).round(3)

            df["z3"] = (df["poh"] - df["pot"]).round(3)

            df["z4"] = df["pot"]

            # df["OFP"] = ((df["z1"] * .165).round(3) + (df["z2"] * .415).round(3) + (df["z3"] * .585).round(3) + (df["z4"] * .835).round(3)).round(3)

            df["AFP"] = ((df["z2"] * .415).round(3) + (df["z3"] * .585).round(3) + (df["z4"] * .835).round(3)).round(3)

            df["tZ"] = ((df["RAW"] * df["AFP"])).round(3)

            #other pure stats:

            #Pressure:

            df["mShPG"] = (df['ShPG'] - df['GPG']).round(2)

            #Defense:

            df["mShA"] = ((df['ShAPG'] - df['GAPG'])).round(2)

            df["SvpmShA"] = (df["SvPG"] / (df["mShA"])).round(2)

            #AA

            df["SvpAA"] = (df["SvPG"] / (df["AAPG"])).round(2)

            #GA

            df["SvpGA"] = (df["SvPG"] / df["GAPG"]).round(2)

            ### DATASET CREATION ###

            # Get tier-specific GP Thresholds and tier z-scores to make the dataset:

            tierMaxG = df.groupby("Tier")["GP"].max().rename("TierMaxGames")

            df = df.merge(tierMaxG, on="Tier", how="left")

            df["GPThreshold"] = (0.6 * df["TierMaxGames"]).round()  # 60% threshold

            qualified = df["GP"] >= df["GPThreshold"]
            dataset = df[qualified].copy()

            stats_averages = ["PPG", "GPG", "APG", "ShPG", "ShPCT", "SvPG", "GAPG", "AAPG", "ShAPG", "RAW", "DI", "DT", "pdt",
                            "pnt", "pot", "AFP", "tZ", "mShPG", "mShA", "SvpmShA", "SvpAA", "SvpGA",]

            tier_stats = (
                dataset
                .groupby("Tier")[stats_averages]
                .agg(["mean", "std"])
            )

            tier_stats.columns = ["_".join(col) for col in tier_stats.columns]

            df = df.merge(tier_stats, on="Tier", how="left")

            for col in stats_averages:
                mean_col = f"{col}_mean"
                std_col  = f"{col}_std"
                z_col    = f"{col}_z" 

                # Avoid division by zero
                df[z_col] = (df[col] - df[mean_col]) / df[std_col].replace(0, pd.NA)

            #Invert Z-scores for stats against
            df["GAPG_z"] = (df["GAPG_z"] * -1)
            df["ShAPG_z"] = (df["ShAPG_z"] * -1)
            df["AAPG_z"] = (df["AAPG_z"] * -1)
            df["DT_z"] = (df["DT_z"] * -1)
            df["mShA_z"] = (df["mShA_z"] * -1)

            #Replace tZ and Demo nans 

            df["RAW_z"] = df["RAW_z"].fillna(df["RAW_mean"])

            df["tZ_z"] = df["tZ_z"].fillna(df["RAW_z"])

            df["DI_z"] = df["DI_z"].fillna(0)

            df["DT_z"] = df["DT_z"].fillna(0)

            ### Z scores for raw stats ###

            df["RvShA"] = (df["RAW_z"] + (df["ShAPG_z"])).round(2)
            df["RvAA"] = (df["RAW_z"] + (df["AAPG_z"])).round(2)

            qualified = df["GP"] >= df["GPThreshold"]
            dataset = df[qualified].copy()

            stats_averages = ["RvShA", "RvAA"]

            tier_stats = (
                dataset
                .groupby("Tier")[stats_averages]
                .agg(["mean", "std"])
            )

            tier_stats.columns = ["_".join(col) for col in tier_stats.columns]

            df = df.merge(tier_stats, on="Tier", how="left")

            for col in stats_averages:
                mean_col = f"{col}_mean"
                std_col  = f"{col}_std"
                z_col    = f"{col}_z"   

                # Avoid division by zero
                df[z_col] = (df[col] - df[mean_col]) / df[std_col].replace(0, pd.NA)

            ### new def stats and z scores ###

            df['RSvA'] = round((df['RvAA_z'] * .47)  +  (df['SvpAA_z'] * .53), 4)

            df['DWR'] = round((df['SvpmShA'] * df["RAW"]), 4)

            # Get RSvA and RpShA  Z-scores

            qualified = df["GP"] >= df["GPThreshold"]
            dataset = df[qualified].copy()

            stats_averages = ["RSvA", "DWR",]

            tier_stats = (
                dataset
                .groupby("Tier")[stats_averages]
                .agg(["mean", "std"])
            )

            tier_stats.columns = ["_".join(col) for col in tier_stats.columns]

            df = df.merge(tier_stats, on="Tier", how="left")

            for col in stats_averages:
                mean_col = f"{col}_mean"
                std_col  = f"{col}_std"
                z_col    = f"{col}_z" 

                # Avoid division by zero
                df[z_col] = (df[col] - df[mean_col]) / df[std_col].replace(0, pd.NA)

            ### Weights for defensive stats ###

            df['RSvA_w'] = round((df['RSvA_z'] * .18), 4)

            df['SvpGA_w'] = round((df['SvpGA_z'] * .30), 4)

            df['DWR_w'] = round((df['DWR_z'] * .34), 4)

            df['RvShA_w'] = round((df['RvShA_z'] * .18), 4)

            df['SvpGA_s'] = round((df['SvpGA_z'] * .45), 4)
            df['RSvA_s'] = round((df['RSvA_z'] * .275), 4)
            df['RvShA_s'] = round((df['RvShA_z'] * .275), 4)

            ### CATEGORY STATS ###

            #DEF

            df['DEF'] = df['SvpGA_w'] + df['DWR_w']  + df['RSvA_w'] + df['RvShA_w']

            #DEFS

            df['DEFS'] = df['SvpGA_s'] + df['RSvA_s'] + df['RvShA_s']

            #PRES

            df["PRES"] = round((df['tZ_z']) + (df['mShPG_z']), 4)

            #ATT STAT

            df["ATT"] = ((df["GPG"] * 100) + (df["ShPG"] * 10) + (df["ShPCT"]))


            # Get DEF, ATT, and PRES Z-scores

            qualified = df["GP"] >= df["GPThreshold"]
            dataset = df[qualified].copy()

            stats_averages = ["DEF", "DEFS", "PRES", "ATT",]

            tier_stats = (
                dataset
                .groupby("Tier")[stats_averages]
                .agg(["mean", "std"])
            )

            tier_stats.columns = ["_".join(col) for col in tier_stats.columns]

            df = df.merge(tier_stats, on="Tier", how="left")

            for col in stats_averages:
                mean_col = f"{col}_mean"
                std_col  = f"{col}_std"
                z_col    = f"{col}_z"  

                # Avoid division by zero
                df[z_col] = (df[col] - df[mean_col]) / df[std_col].replace(0, pd.NA)

            #.52 .36 .44 = 1.32

            df['RAD'] = ((df['DEF_z'] * .33) + (df['PRES_z'] * .27) + (df['ATT_z'] * .40))

            #.52 .36 .58 = 1.46

            df['RADS'] = ((df['DEFS_z'] * .40) + (df['PRES_z'] * .24) + (df['ATT_z'] * .36))


            df["PvShA"] = round((df['PRES_z']) + (df['ShAPG_z']), 4)

            ### RAD Z-scores ###

            qualified = df["GP"] >= df["GPThreshold"]
            dataset = df[qualified].copy()

            stats_averages = ["RAD", "RADS",]

            tier_stats = (
                dataset
                .groupby("Tier")[stats_averages]
                .agg(["mean", "std"])
            )

            tier_stats.columns = ["_".join(col) for col in tier_stats.columns]

            df = df.merge(tier_stats, on="Tier", how="left")

            for col in stats_averages:
                mean_col = f"{col}_mean"
                std_col  = f"{col}_std"
                z_col    = f"{col}_z"  

                # Avoid division by zero
                df[z_col] = (df[col] - df[mean_col]) / df[std_col].replace(0, pd.NA)


            ######################################################################################################################################################################
            # region 5) save sheets
            ######################################################################################################################################################################


            # d = dtale.show(df)
            # d.open_browser()
            # input("Press Enter to exit...")   
            #If successful, save these sheets to the cache

            bot.dfmast = df

            #And create the backup

            df.to_csv('cache/dfmast.csv', index=False)
            dfI.to_csv('cache/dfI.csv', index=False)
            dfTEAM.to_csv('cache/dfTEAM.csv', index=False)
            dfTOT.to_csv('cache/dfTOT.csv', index=False)
            dfROSTER.to_csv('cache/dfROSTER.csv', index=False)

            print("♻️ Sheets loaded and Cache refreshed! ♻️")
            await asyncio.sleep(60 * 60 * 1)  # 1 hour

        except (Exception) as e:
            if not bot.dfs:
                print(f"❌  Cache sheet parsing failed: {e}. Trying again in 10 minutes  ❌")
                traceback.print_exc()
                await asyncio.sleep(600)
            else:
                print("✅⚠️  No new sheets available. Keeping old cache...  ⚠️✅")
                await asyncio.sleep(60 * 60 * 1)



