#Search Autocomplete (TC)
async def trophy_player_autocomplete(interaction, current: str):
    
    dfdat = pd.read_csv('careercache/vmast.csv')

    players = dfdat["Name"].fillna("").astype(str).drop_duplicates()


    matches = [
        app_commands.Choice(name=p, value=p)
        for p in players
        if current.lower() in p.lower()
    ]
    return matches[:10]

def not_empty(row, cols):
    for col in cols:
        val = row[col]
        if pd.notna(val) and str(val).strip():
            return col, val
    return None, None

def safe_lower(val):
    if pd.isna(val):
        return ""
    return str(val).strip().casefold()

