#SEARCH ASSIST (Current Season)

def search_players(query: str, limit: int = 10):
    #case-insensitive filter
    mask = bot.dfdat["Name"].str.contains(query, case=False, na=False)
    matches = bot.dfdat[mask]["Name"].head(limit).tolist()
    return matches

def search_tier(query: str, limit: int = 10):
    #case-insensitive filter
    mask = bot.dftiers["Tier"].str.contains(query, case=False, na=False)
    matches = bot.dftiers[mask]["Tier"].head(limit).tolist()
    return matches

def search_team(query: str, limit: int = 10):
    #case-insensitive filter
    mask = bot.dfteam["Team"].str.contains(query, case=False, na=False)
    matches = bot.dfteam[mask]["Team"].head(limit).tolist()
    return matches


#Search Autocomplete (Present Season)

async def player_autocomplete(interaction, current: str):
    matches = search_players(current)
    return [app_commands.Choice(name=m, value=m) for m in matches]

async def tier_autocomplete(interaction, current: str):
    matches = search_tier(current)
    return [app_commands.Choice(name=m, value=m) for m in matches]

async def team_autocomplete(interaction, current: str):
    matches = search_team(current)
    return [app_commands.Choice(name=m, value=m) for m in matches]

