#PARSE THROUGH GAMES FUNCTIONS

def _pick_col(dfga: pd.DataFrame, candidates: list[str]) -> str:
    """Pick the first matching column name (case-insensitive)."""
    lower_map = {c.lower(): c for c in dfga.columns}
    for cand in candidates:
        if cand.lower() in lower_map:
            return lower_map[cand.lower()]
    raise KeyError(f"None of these columns were found: {candidates}\nFound: {list(dfga.columns)}")

def _normalize_player_key(s: pd.Series) -> pd.Series:
    """Make a stable-ish key from names if you don't have platform IDs."""
    return (
        s.astype(str)
         .str.strip()
         .str.lower()
         .str.replace(r"\s+", " ", regex=True)
    )

def process_ballchasing_match_csv(filepath: str) -> pd.DataFrame:
    """
    Returns per-player per-match rows with:
      player_key, team, assists_against, accolades, match_file
    """
    df = pd.read_csv(filepath)

    # --- adjust these candidates to match your export columns ---
    name_col = _pick_col(df, ["player", "name", "player name"])
    team_col = _pick_col(df, ["team", "color", "side"])
    assists_col = _pick_col(df, ["assists", "a"])
    goals_col = _pick_col(df, ["goals", "g"])
    saves_col = _pick_col(df, ["saves", "sv", "s"])

    work = df[[name_col, team_col, assists_col, goals_col, saves_col]].copy()
    work.rename(columns={
        name_col: "player",
        team_col: "team",
        assists_col: "assists",
        goals_col: "goals",
        saves_col: "saves",
    }, inplace=True)

    # Normalize types
    work["assists"] = pd.to_numeric(work["assists"], errors="coerce").fillna(0).astype(int)
    work["goals"]   = pd.to_numeric(work["goals"], errors="coerce").fillna(0).astype(int)
    work["saves"]   = pd.to_numeric(work["saves"], errors="coerce").fillna(0).astype(int)

    # If team values are like "Blue"/"Orange" (or 0/1), normalize them
    # This mapping is intentionally forgiving:
    t = work["team"].astype(str).str.strip().str.lower()
    work["team_norm"] = t.replace({
        "0": "blue", "1": "orange",
        "blue": "blue", "orange": "orange",
        "b": "blue", "o": "orange",
    })

    # If still not just blue/orange, you can inspect unique values:
    # print(filepath, work["team"].unique())

    # Player key (prefer platform id if you have it; otherwise name key)
    work["player_key"] = _normalize_player_key(work["player"])

    # Compute opponent total assists
    assists_by_team = work.groupby("team_norm")["assists"].sum().to_dict()
    blue_total = assists_by_team.get("blue", 0)
    orange_total = assists_by_team.get("orange", 0)

    def assists_against_for(team_norm: str) -> int:
        if team_norm == "blue":
            return orange_total
        if team_norm == "orange":
            return blue_total
        return 0

    work["assists_against"] = work["team_norm"].map(assists_against_for).astype(int)

    # Accolades: floor(goals/3)+floor(assists/3)+floor(saves/3)
    work["accolades"] = (work["goals"] // 3) + (work["assists"] // 3) + (work["saves"] // 3)

    work["match_file"] = os.path.basename(filepath)

    return work[["player_key", "player", "team_norm", "assists_against", "accolades", "match_file"]]

def process_folder_of_games(folder: str) -> pd.DataFrame:
    all_rows = []
    for fp in glob.glob(os.path.join(folder, "*.csv")):
        all_rows.append(process_ballchasing_match_csv(fp))

    long_df = pd.concat(all_rows, ignore_index=True)

    # Aggregate across games
    agg = (long_df.groupby("player_key")
                 .agg(
                     player=("player", "first"),
                     games_played=("match_file", "nunique"),
                     assists_against_total=("assists_against", "sum"),
                     ACC=("accolades", "sum"),
                 )
                 .reset_index())

    # Optional: per-game averages
    agg["assists_against_pg"] = agg["assists_against_total"] / agg["games_played"].clip(lower=1)

    return agg, long_df

#Safe File names

def safe_filename(name):
    return re.sub(r'[\\/*?:"<>|]', "", name)

#Text Thingies

def _casefold(s): 
    return "" if pd.isna(s) else str(s).casefold().strip()

def _norm_result(s):
    if pd.isna(s): 
        return ""
    return str(s).replace("–", "-").replace("—", "-").strip()


#SEND 10+ Images (Group)

def chunk_list(lst, size):
    for i in range(0, len(lst), size):
        yield lst[i:i + size]

