@bot.tree.command(
    name="powerrank",
    description="Show the top 8 teams in a tier by RAD"
)
@app_commands.describe(tier="Choose a tier")
async def powerrank(
    interaction: discord.Interaction,
    tier: str
):
    await handle_powerrank(interaction,
    tier)

@powerrank.autocomplete("tier")
async def powerrank_autocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await tier_autocomplete(interaction, current)

