    values2 += values2[:1]
    values2

    #Create even space on the chart:

    angles = [n / float(N) * 2 * pi for n in range(N)]
    angles += angles[:1]

    #Initialize the polar chart:

    fig = plt.figure(figsize=(6, 6))

    #Set the border

    ax = fig.add_axes([0.17, 0.125, 0.66, 0.66], polar =True)
