    qualified = tierScores["GP"] >= tierScores["GPThreshold"]
    tierScoresRAD = tierScores[qualified].copy()

    LowRAD = round(tierScoresRAD['RAD_z'].quantile([0.33]), 3)

    MidRAD = round(tierScoresRAD['RAD_z'].quantile([0.66]), 3)

