async def handle_rad3(interaction, player, player2, player3):

    ######################################################################################################################################################################
    # region GETINFO
    ######################################################################################################################################################################


    print('❕❕❕  /rad3 RAN BY {}'.format(interaction.user.name))



    await interaction.response.defer(thinking=True)

    try:

        #PARSE ALL SHEETS

        print("📶 Checking master DF...")

        start_time = time.perf_counter()

        df = bot.dfmast

        end_time = time.perf_counter()

        duration = end_time - start_time

        print(f"✅  Master DF loaded in {duration: .2f} seconds")

    except (Exception, asyncio.TimeoutError) as e:
        
        print(f"⚠️   Load error from online DF: {e}. 🛄  Attempting to use cache now...")

        try:

            df = pd.read_csv('cache/dfmast.csv')

            print("✅  Sheets pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframes: {e}. Terminating command")
            await interaction.followup.send("ERROR: A league sheet is currently down or missing data. Please try again in a few minutes")

            return

    #Look for player 1

    pl1 = player

