#RAD3C

@bot.tree.command(
    name="rad3c",
    description="Get three players' stats (combined)"
)
@app_commands.describe(player="Choose a player", player2="Choose a player", player3="Choose a player")
async def rad3c(
    interaction: discord.Interaction,
    player: str,
    player2: str,
    player3: str
):
    await handle_rad3c(interaction,
    player,
    player2,
    player3)

@rad3c.autocomplete("player")
async def rad3c_autocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await player_autocomplete(interaction, current)

@rad3c.autocomplete("player2")
async def rad3c_autocomplete2(
    interaction: discord.Interaction,
    current: str
):
    return await player_autocomplete(interaction, current)

@rad3c.autocomplete("player3")
async def rad3c_autocomplete3(
    interaction: discord.Interaction,
    current: str
):
    return await player_autocomplete(interaction, current)

async def handle_rad3c(interaction, player, player2, player3):

######################################################################################################################################################################
# region GETINFO
######################################################################################################################################################################


    print('❕❕❕  /rad3c RAN BY {}'.format(interaction.user.name))



    await interaction.response.defer(thinking=True)

    try:

        #PARSE ALL SHEETS

        print("📶 Checking master DF...")

        start_time = time.perf_counter()

        df = bot.dfmast

        end_time = time.perf_counter()

        duration = end_time - start_time

        print(f"✅  Master DF loaded in {duration: .2f} seconds")

    except (Exception, asyncio.TimeoutError) as e:
        
        print(f"⚠️   Load error from online DF: {e}. 🛄  Attempting to use cache now...")

        try:

            df = pd.read_csv('cache/dfmast.csv')

            print("✅  Sheets pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframes: {e}. Terminating command")
            await interaction.followup.send("ERROR: A league sheet is currently down or missing data. Please try again in a few minutes")

            return

    #Look for player 1

    pl1 = player

    if pl1.casefold() in df["Name"].str.casefold().tolist():
        print(("☑️  Successful input: " + pl1))
    else:
        await interaction.followup.send("Player not found")
        print("✖️ 🚫  Player not found. Terminating command")
        return
 
    choice = str(pl1)

    #FIND PLAYER ON EACH SHEET AND CREATE NeW STATS

    try:

        player = df[(df['Name'].str.casefold() == choice.casefold())]

        player = player.sort_values("GP", ascending=False, ignore_index=False)

        player = player.groupby('Name', as_index=False).head(1)

    except Exception as e:
        interaction.followup.send("ERROR: Could not load player data from sheets")
        print(f"⛔️  Sheet data error: {e} Could not load player data. Terminating command")
        return

    #Season Info

    szn = int(player["Season"].iloc[0])

    sns = str(f"s{szn}")


    #Print out basic player info

    print("🚺  Player: ", player.iloc[:, : 5].values.tolist())

    #Look for player 2

    pl2 = player2

    if pl2.casefold() in df["Name"].str.casefold().tolist():
        print(("☑️  Successful input: " + pl2))
    else:
        await interaction.followup.send("Player not found")
        print("✖️ 🚫  Player not found. Terminating command")
        return
 
    choice2 = str(pl2)

    #FIND PLAYER ON EACH SHEET AND CREATE NeW STATS

    try:

        player2 = df[(df['Name'].str.casefold() == choice2.casefold())]

        player2 = player2.sort_values("GP", ascending=False, ignore_index=False)

        player2 = player2.groupby('Name', as_index=False).head(1)

    except Exception as e:
        interaction.followup.send("ERROR: Could not load player data from sheets")
        print(f"⛔️  Sheet data error: {e} Could not load player data. Terminating command")
        return

    #Print out basic player info

    print("🚺  Player 2: ", player2.iloc[:, : 5].values.tolist())

    #Look for player 3

    pl3 = player3

    if pl3.casefold() in df["Name"].str.casefold().tolist():
        print(("☑️  Successful input: " + pl3))
    else:
        await interaction.followup.send("Player not found")
        print("✖️ 🚫  Player not found. Terminating command")
        return
 
    choice3 = str(pl3)

    #FIND PLAYER ON EACH SHEET AND CREATE NeW STATS

    try:

        player3 = df[(df['Name'].str.casefold() == choice3.casefold())]

        player3 = player3.sort_values("GP", ascending=False, ignore_index=False)

        player3 = player3.groupby('Name', as_index=False).head(1)

    except Exception as e:
        interaction.followup.send("ERROR: Could not load player data from sheets")
        print(f"⛔️  Sheet data error: {e} Could not load player data. Terminating command")
        return

    #Print out basic player info

