#szntop

@bot.tree.command(
    name="szntop",
    description="Show the top 8 players in a tier by RAD (Past Seasons)"
)
@app_commands.describe(tier="Choose a tier")
async def szntop(
    interaction: discord.Interaction,
    season: str,
    tier: str
):
    await handle_szntop(interaction,
    season,
    tier)

@szntop.autocomplete("season")
async def szntop_seasonautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await season_autocomplete(interaction, current)

@szntop.autocomplete("tier")
async def szntop_autocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await tier_autocomplete(interaction, current)

async def handle_szntop(interaction, season, tier):

    print('❕❕❕  /szntop RAN BY {}'.format(interaction.user.name))

    await interaction.response.defer(thinking=True)

    try:

        #PARSE ALL SHEETS

        print("📶 Checking master DF...")

        start_time = time.perf_counter()

        ssi = int(season)

        df = pd.read_csv(f"cache/dfmast{ssi}.csv")

        end_time = time.perf_counter()

        duration = end_time - start_time

        print(f"✅  Master DF loaded in {duration: .2f} seconds")

    except (Exception, asyncio.TimeoutError) as e:
        
        print(f"⚠️   Load error from online DF: {e}. 🛄  Attempting to use cache now...")

        try:

            ssi = int(season)

            df = pd.read_csv(f"'cache/dfmast{ssi}.csv")

            print("✅  Sheets pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframes: {e}. Terminating command")
            await interaction.followup.send("ERROR: A league sheet is currently down or missing data. Please try again in a few minutes")

            return

    tir = str(tier)

    if tir.casefold() in df["Tier"].str.casefold().tolist():
        print(("☑️  Successful input: " + tir))
    else:
        await interaction.followup.send("Tier not found: + " + tir)
        print("✖️ 🚫  Tier not found. Terminating command")
        return

    files=[]

    tierdf = df[df["Tier"].str.casefold() == tir.casefold()]

    qualified = tierdf["GP"] >= tierdf["GPThreshold"]
