#SZNT

@bot.tree.command(
    name="sznt",
    description="Get a team's players from a specific season"
)
@app_commands.describe(season ="Choose the season", team="Choose a team")
async def sznt(
    interaction: discord.Interaction,
    season: str,
    team: str
):
    await handle_sznt(interaction, season, team)

@sznt.autocomplete("season")
async def sznt_seasonautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await season_autocomplete(interaction, current)

@sznt.autocomplete("team")
async def sznt_teamautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await team_old_autocomplete(interaction, current)

