    traitz = ["$\\bf{Guardian}$", "$\\bf{Bouncer}$", "$\\bf{♠Titan♠}$", "$\\bf{♠Adamantine♠}$","$\\bf{Dynamo}$","$\\bf{Marksman}$","$\\bf{Engine}$","$\\bf{Dreadnought}$","$\\bf{Sentinel}$","$\\bf{Phalanx}$",
            "$\\bf{Wizard}$","$\\bf{Sorcerer}$","$\\bf{Warlock}$","$\\bf{Jet}$","$\\bf{Ninja}$",
            "$\\bf{Shadow}$","$\\bf{Berserker}$","$\\bf{Gladiator}$","$\\bf{Enforcer}$","$\\bf{Assassin}$","$\\bf{Angel}$","$\\bf{Hunter}$",
            "$\\bf{♠♠♠Unemployed♠♠♠}$","$\\bf{♠Leviathan♠}$","$\\bf{♠Colossus♠}$","$\\bf{♠Warden♠}$","$\\bf{♠♠♠♠\\ CEO\\ of\\ Unemployment\\ ♠♠♠♠}$","$\\bf{♠Menace♠}$","$\\bf{♠Phantom♠}$","$\\bf{♠Reaper♠}$"]

