#SZNTIER

@bot.tree.command(
    name="szntier",
    description="Get a player's card from a specific season for a specific tier"
)
@app_commands.describe(season ="Choose the season", tier ="Choose a tier", player="Choose a player")
async def szntier(
    interaction: discord.Interaction,
    season: str,
    tier: str,
    player: str
):
    await handle_szntier(interaction, season, tier, player)

@szntier.autocomplete("season")
async def szntier_seasonautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await season_autocompletet(interaction, current)

@szntier.autocomplete("tier")
async def szntier_tierautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await tier_autocomplete(interaction, current)


@szntier.autocomplete("player")
async def szntier_playerautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await player_old_autocomplete(interaction, current)

async def handle_szntier(interaction, season, tier, player):

######################################################################################################################################################################
# region GETINFO
######################################################################################################################################################################



    print('❕❕❕  /szntier RAN BY {}'.format(interaction.user.name))



    await interaction.response.defer(thinking=True)

    try:

        #PARSE ALL SHEETS

        print("📶 Checking master DF...")

        start_time = time.perf_counter()

        ssi = int(season)

        df = pd.read_csv(f"cache/dfmast{ssi}.csv")
    

        end_time = time.perf_counter()

        duration = end_time - start_time

        print(f"✅  Master DF loaded in {duration: .2f} seconds")

    except (Exception, asyncio.TimeoutError) as e:
        
        print(f"⚠️   Load error from online DF: {e}. 🛄  Attempting to use cache now...")

        try:

            ssi = int(season)

            df = pd.read_csv(f"cache/dfmast{ssi}.csv")
        
            print("✅  Sheets pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframes: {e}. Terminating command")
            await interaction.followup.send("ERROR: A league sheet is currently down or missing data. Please try again in a few minutes")

            return

    #Look up tier

    tiers = ["Premier", "Master", "Elite", "Veteran", "Rival", "Challenger", "Prospect", "Contender", "Amateur", ]

    tr1 = tier

    if tr1.casefold() in df["Tier"].str.casefold().tolist():
        print(("☑️  Successful Tier input: " + tr1))
    else:
        await interaction.followup.send("Tier not found")
        print("✖️ 🚫  Tier not found. Terminating command")
        return

    choicetier = str(tr1)

    df = df[(df['Tier'].str.casefold() == choicetier.casefold())]

    pl1 = player

    if pl1.casefold() in df["Name"].str.casefold().tolist():
        print(("☑️  Successful input: " + pl1))
    else:
        await interaction.followup.send("Player not found")
        print("✖️ 🚫  Player not found. Terminating command")
        return
 
    choice = str(pl1)

    #FIND PLAYER ON EACH SHEET AND CREATE NeW STATS


    try:

        player = df[(df['Name'].str.casefold() == choice.casefold())]

        player = player.sort_values("GP", ascending=False, ignore_index=False)

        player = player.groupby('Name', as_index=False).head(1)

    except Exception as e:
        interaction.followup.send("ERROR: Could not load player data from sheets")
        print(f"⛔️  Sheet data error: {e} Could not load player data. Terminating command")
        return

    #Look for PFP

    try:

        rscid = str(player["RSC ID"].iloc[0])

        mmsup = bot.mmsup

        mrow = mmsup[mmsup["RSC ID"].astype(str) == str(rscid)]

        discord_id = int(mrow["Discord ID"].iloc[0])

        user = bot.get_user(discord_id)

        if user is None:
            user = await bot.fetch_user(discord_id)

        avatar = user.display_avatar.url

        async with aiohttp.ClientSession() as session:
            async with session.get(avatar) as resp:
                avatar_bytes = await resp.read()

        avatar_img = Image.open(BytesIO(avatar_bytes))

        print(f"⚛️  Discord ID Found")

        print(discord_id)

    except Exception as e:
        print(f"⚠️  ALERT: No Discord ID Found: {e}")
        discord_id = int(0)


    #Season Info

    szn = int(player["Season"].iloc[0])

    sns = str(f"s{szn}")



    #Print out basic player info

    print("🚺  Player: ", player.iloc[:, : 5].values.tolist())

    #Grab the player's key stats:

    GP = int(player["GP"].iloc[0])


    #CONVERT ALL Z SCORES TO PERCENTILES

    pShPG = float(st.norm.cdf(player["ShPG_z"].iloc[0]).round(2))
    pmShPG = float(st.norm.cdf(player["mShPG_z"].iloc[0]).round(2))

    pGPG = float(st.norm.cdf(player["GPG_z"].iloc[0]).round(2))
    pShPCT = float(st.norm.cdf(player["ShPCT_z"].iloc[0]).round(2))
    pATT = float(st.norm.cdf(player["ATT_z"].iloc[0]).round(4))

    pRAW = float(st.norm.cdf(player["RAW_z"].iloc[0]).round(2))

    ptZ = float(st.norm.cdf(player["tZ_z"].iloc[0]).round(2))
    pPRES = float(st.norm.cdf(player["PRES_z"].iloc[0]).round(4))

    pDIPG = float(st.norm.cdf(player["DI_z"].iloc[0]).round(2))
    pDTPG = float(st.norm.cdf(player["DT_z"].iloc[0]).round(2))

    pSvpGA = float(st.norm.cdf(player["SvpGA_z"].iloc[0]).round(2))
    pRSvA = float(st.norm.cdf(player["RSvA_z"].iloc[0]).round(2))
    pDWR = float(st.norm.cdf(player["DWR_z"].iloc[0]).round(2))
    pRvShA = float(st.norm.cdf(player["RvShA_z"].iloc[0]).round(2))
    pDEF = float(st.norm.cdf(player["DEF_z"].iloc[0]).round(4))

    pRAD = float(st.norm.cdf(player["RAD_z"].iloc[0]).round(4))

    pAPG = float(st.norm.cdf(player["APG_z"].iloc[0]).round(2))

    pSvPG = float(st.norm.cdf(player["SvPG_z"].iloc[0]).round(2))



    #HUNDREDS ZONE

    if 1 == 1:

        #ATT
        if pATT >= .9995:
            pATT = 1.10
        elif pATT >= .999:
            pATT = 1.09
        elif pATT >= .998:
            pATT = 1.08
        elif pATT >= .997:
            pATT = 1.07
