#SZN2

@bot.tree.command(
    name="szn2",
    description="Get a player's card from a specific season"
)
@app_commands.describe(season ="Choose the season", player="Choose a player", player2="Choose a player")
async def szn2(
    interaction: discord.Interaction,
    season: str,
    player: str,
    player2: str,
):
    await handle_szn2(interaction, season, player, player2)

@szn2.autocomplete("season")
async def szn2_seasonautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await season_autocomplete(interaction, current)

@szn2.autocomplete("player")
async def szn2_playerautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await player_old_autocomplete(interaction, current)

@szn2.autocomplete("player2")
async def szn2_playerautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await player_old_autocomplete(interaction, current)

async def handle_szn2(interaction, season, player, player2):

######################################################################################################################################################################
# region GETINFO
######################################################################################################################################################################



    print('❕❕❕  /szn2 RAN BY {}'.format(interaction.user.name))



    await interaction.response.defer(thinking=True)

    try:

        #PARSE ALL SHEETS

        print("📶 Checking master DF...")

        start_time = time.perf_counter()

        ssi = int(season)

        df = pd.read_csv(f"cache/dfmast{ssi}.csv")
    

        end_time = time.perf_counter()

        duration = end_time - start_time

        print(f"✅  Master DF loaded in {duration: .2f} seconds")

    except (Exception, asyncio.TimeoutError) as e:
        
        print(f"⚠️   Load error from online DF: {e}. 🛄  Attempting to use cache now...")

        try:

            ssi = int(season)

            df = pd.read_csv(f"cache/dfmast{ssi}.csv")
        
            print("✅  Sheets pulled from cache")

        except Exception as e:
            print(f"⛔️  ERROR: Failed to substitute cached dataframes: {e}. Terminating command")
            await interaction.followup.send("ERROR: A league sheet is currently down or missing data. Please try again in a few minutes")

            return

