#SZN3

@bot.tree.command(
    name="szn3",
    description="Get a player's card from a specific season"
)
@app_commands.describe(season ="Choose the season", player="Choose a player", player2="Choose a player", player3="Choose a player")
async def szn3(
    interaction: discord.Interaction,
    season: str,
    player: str,
    player2:str,
    player3:str,
):
    await handle_szn3(interaction, season, player, player2, player3)

@szn3.autocomplete("season")
async def szn3_seasonautocomplete(
    interaction: discord.Interaction,
    current: str
):
    return await season_autocomplete(interaction, current)

